 "content": "def transform(grid):
    """Translate the non-background pattern down one row, clipping at the edge."""
    h, w = len(grid), len(grid[0])
    background = max(range(10), key=lambda color: sum(cell == color for row in grid for cell in row))
    out = [[background for _ in range(w)] for _ in range(h)]
    for r in range(h - 1):
        for c in range(w):
            if grid[r][c] != background:
                out[r + 1][c] = grid[r][c]
    return out
